import 'package:flutter/material.dart';import '../../../core/models/zodiac_sign.dart';import '../../../core/data/astro_repository.dart';import '../../../core/theme/app_theme.dart';import '../../../shared/widgets/app_components.dart';
class ZodiacScreen extends StatefulWidget{const ZodiacScreen({super.key});@override State<ZodiacScreen> createState()=>_ZodiacScreenState();}
class _ZodiacScreenState extends State<ZodiacScreen>{String query='';@override Widget build(BuildContext context){final rows=zodiacSigns.where((s)=>s.name.toLowerCase().contains(query.toLowerCase())).toList();return CustomScrollView(slivers:[SliverPadding(padding:const EdgeInsets.all(20),sliver:SliverToBoxAdapter(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const PageHeader('The zodiac',subtitle:'Twelve signs and their traditional associations.'),TextField(onChanged:(v)=>setState(()=>query=v),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Search signs'))]))),SliverPadding(padding:const EdgeInsets.symmetric(horizontal:18),sliver:SliverGrid.builder(itemCount:rows.length,gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:2,childAspectRatio:1.35,crossAxisSpacing:10,mainAxisSpacing:10),itemBuilder:(c,i){final s=rows[i];return Card(child:InkWell(onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>SignProfileScreen(sign:s))),child:Padding(padding:const EdgeInsets.all(15),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(s.glyph,style:const TextStyle(fontSize:29,color:AppTheme.primary)),const Spacer(),Text(s.name,style:const TextStyle(fontSize:16,fontWeight:FontWeight.w700)),Text(s.dates,style:const TextStyle(fontSize:11,color:AppTheme.muted)),Text(s.element+' · '+s.modality,style:const TextStyle(fontSize:10,color:AppTheme.primary))]))));}))]);}}
class SignProfileScreen extends StatelessWidget{const SignProfileScreen({super.key,required this.sign});final ZodiacSign sign;@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(sign.name)),body:ListView(padding:const EdgeInsets.all(22),children:[Center(child:Text(sign.glyph,style:const TextStyle(fontSize:75,color:AppTheme.primary))),Center(child:Text(sign.dates,style:const TextStyle(color:AppTheme.muted))),const SizedBox(height:18),Text(sign.about,style:Theme.of(context).textTheme.bodyLarge),_row('Element',sign.element),_row('Modality',sign.modality),_row('Ruling planet',sign.ruler),FilledButton.icon(onPressed:()async{await AstroRepository.instance.toggleSaved({'id':'sign-'+sign.id,'sign':sign.id,'title':sign.name+' · Zodiac profile','body':sign.about,'prompt':'Explore '+sign.element+' and '+sign.modality+' traditions.','content_type':'sign'});if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Zodiac profile saved locally.')));},icon:const Icon(Icons.bookmark_add_outlined),label:const Text('Save sign')),const InfoCard('These are traditional cultural associations, not fixed descriptions or scientific personality assessments.'),const DisclaimerCard()]));Widget _row(String a,String b)=>ListTile(title:Text(a,style:const TextStyle(color:AppTheme.muted)),trailing:Text(b,style:const TextStyle(fontWeight:FontWeight.w700)));}
